.body-redirect {
   background-color: black;
   color: white;
   font-family: sans-serif;
}

.page-redirect-custom {
    min-height: 80vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.loading-msg {
   text-align: center;
}

.loading-msg img {
    max-width: 200px;
    width: 100%;
    height: auto;
    margin-bottom: 30px;
}

.loading-msg h1 {
    font-family: "Courier New", Courier, monospace;
    font-size: 3rem;
    color: #FFFFFF;
    margin-bottom: 20px;
}

.loading-msg p {
    font-family: "Courier New", Courier, monospace;
    font-size: 1.25rem;
    color: #CCCCCC;
    opacity: 1;
}

/* Simple loading animation */
.spinner {
    border: 4px solid rgba(255, 255, 255, 0.3);
    border-top: 4px solid #FFFFFF;
    border-radius: 50%;
    width: 50px;
    height: 50px;
    animation: spin 1s linear infinite;
    margin: 20px auto;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}
